import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { publicAPI } from '../../services/api';
import Card from '../../components/Card';
import Loader from '../../components/Loader';
import EmptyState from '../../components/EmptyState';
import Button from '../../components/Button';

// Reuse the SVG India Flag
const IndiaFlag = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="16" viewBox="0 0 301 201" style={{ borderRadius: '2px', display: 'inline-block', verticalAlign: 'middle' }}>
    <g fill="none">
      <path fill="#f93" d="M.5.5h300v200H.5z" />
      <path fill="#fff" d="M.5 67.166h300v66.667H.5z" />
      <path fill="#128807" d="M.5 133.833h300V200.5H.5z" />
      <circle cx="150.5" cy="100.5" r="26.667" fill="#008" />
      <circle cx="150.5" cy="100.5" r="23.333" fill="#fff" />
      <circle cx="150.5" cy="100.5" r="4.667" fill="#008" />
    </g>
  </svg>
);

const CATEGORIES = ['ALL', 'WASTE_SEGREGATION', 'THREE_R', 'SUSTAINABILITY', 'CLEAN_INDIA_MISSION', 'GREEN_ENERGY'];

/**
 * Enhanced Blog Card with Hover Effects and Professional Metadata
 */
const BlogCard = ({ blog }) => (
  <Link to={`/blogs/${blog.slug}`} style={{ textDecoration: 'none' }}>
    <Card hover style={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      <div style={{
        height: '180px',
        background: 'linear-gradient(135deg, var(--eco-bg) 0%, var(--eco-success-bg) 100%)',
        borderRadius: 'var(--radius-md) var(--radius-md) 0 0',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontSize: '40px'
      }}>
        {blog.category === 'WASTE_SEGREGATION' ? '♻️' : blog.category === 'THREE_R' ? '🔄' : '🌿'}
      </div>
      <Card.Body style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        <span className="badge badge--neutral" style={{
          marginBottom: 'var(--space-3)',
          textTransform: 'uppercase',
          fontSize: '10px',
          fontWeight: 700,
          letterSpacing: '0.8px',
          color: 'var(--eco-primary)'
        }}>
          {blog.category?.replace('_', ' ')}
        </span>
        <h3 style={{
          fontFamily: 'var(--font-display)',
          fontSize: 'var(--text-lg)',
          fontWeight: 700,
          color: 'var(--eco-text)',
          marginBottom: 'var(--space-2)',
          lineHeight: 1.3
        }}>
          {blog.title}
        </h3>
        <p style={{
          fontSize: 'var(--text-sm)',
          color: 'var(--eco-text-secondary)',
          lineHeight: 1.6,
          marginBottom: 'var(--space-4)',
          flex: 1
        }}>
          {blog.content?.slice(0, 140)}...
        </p>
        <div style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          paddingTop: 'var(--space-4)',
          borderTop: '1px solid var(--eco-border)',
          fontSize: 'var(--text-xs)',
          color: 'var(--eco-text-muted)'
        }}>
          <span style={{ fontWeight: 600 }}>👤 {blog.author}</span>
          <span>📅 {new Date(blog.createdAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</span>
        </div>
      </Card.Body>
    </Card>
  </Link>
);

/**
 * Featured Blog Section (First Post in List)
 */
const FeaturedBlog = ({ blog }) => (
  <div style={{
    background: 'var(--eco-surface)',
    borderRadius: 'var(--radius-lg)',
    border: '1px solid var(--eco-border)',
    overflow: 'hidden',
    marginBottom: 'var(--space-12)',
    boxShadow: 'var(--shadow-lg)',
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))'
  }}>
    <div style={{ padding: 'var(--space-10)', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '12px' }}>
        <span style={{ color: 'var(--eco-primary)', fontWeight: 800, fontSize: '12px', textTransform: 'uppercase' }}>⭐ Featured Article</span>
        <IndiaFlag />
      </div>
      <h2 style={{ fontSize: '32px', fontWeight: 800, marginBottom: '16px', lineHeight: 1.2 }}>{blog.title}</h2>
      <p style={{ color: 'var(--eco-text-secondary)', marginBottom: '24px', fontSize: '16px', lineHeight: 1.6 }}>
        {blog.content?.slice(0, 250)}...
      </p>
      <Link to={`/blogs/${blog.slug}`}>
        <Button variant="primary" style={{ width: 'fit-content' }}>Read Full Story</Button>
      </Link>
    </div>
    <div style={{
      background: 'var(--eco-primary-light)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontSize: '120px'
    }}>🌏</div>
  </div>
);

/**
 * Sidebar / Newsletter Component
 */
const NewsletterBox = () => (
  <div style={{
    padding: '32px',
    background: 'var(--eco-text)',
    borderRadius: 'var(--radius-lg)',
    color: 'white',
    textAlign: 'center'
  }}>
    <h3 style={{ fontSize: '24px', marginBottom: '12px' }}>Join the Green Movement</h3>
    <p style={{ opacity: 0.8, marginBottom: '24px', fontSize: '14px' }}>Get weekly tips on waste segregation and sustainability in India.</p>
    <div style={{ display: 'flex', gap: '8px' }}>
      <input
        type="email"
        placeholder="your@email.com"
        style={{
          flex: 1,
          padding: '12px',
          borderRadius: '8px',
          border: 'none',
          outline: 'none'
        }}
      />
      <Button variant="primary">Subscribe</Button>
    </div>
  </div>
);

const BlogsPage = () => {
  const [blogs, setBlogs]           = useState([]);
  const [loading, setLoading]       = useState(true);
  const [error, setError]           = useState('');
  const [page, setPage]             = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [category, setCategory]     = useState('ALL');

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setLoading(true);
    const cat = category === 'ALL' ? '' : category;

    publicAPI.getBlogs(page, 9, cat)
      .then(res => {
        setBlogs(res.data.content);
        setTotalPages(res.data.totalPages);
      })
      .catch(() => setError('Oops! Unable to fetch our green journals. Please try again later.'))
      .finally(() => setLoading(false));
  }, [page, category]);

  return (
    <div style={{ background: 'var(--eco-bg)', minHeight: '100vh', paddingBottom: '80px' }}>
      {/* ── Section 1: Hero Header ── */}
      <div style={{
        background: 'linear-gradient(to bottom, #f0fdf4, var(--eco-bg))',
        padding: '100px 24px 60px',
        textAlign: 'center',
        borderBottom: '1px solid var(--eco-border)'
      }}>
        <div style={{
          display: 'inline-flex',
          alignItems: 'center',
          gap: '10px',
          padding: '8px 16px',
          background: 'white',
          borderRadius: '50px',
          boxShadow: '0 4px 12px rgba(0,0,0,0.05)',
          marginBottom: '24px'
        }}>
          <IndiaFlag />
          <span style={{
            fontFamily: "'Teko', sans-serif",
            fontSize: '22px',
            fontWeight: 500,
            letterSpacing: '1px',
            color: 'var(--eco-text)'
          }}>स्वच्छ भारत | विकसित भारत</span>
        </div>
        <h1 style={{
          fontFamily: 'var(--font-display)',
          fontSize: 'clamp(40px, 5vw, 64px)',
          fontWeight: 900,
          color: 'var(--eco-text)',
          marginBottom: '16px'
        }}>
          Awareness <span style={{ color: 'var(--eco-primary)' }}>Journals</span>
        </h1>
        <p style={{
          fontSize: '18px',
          color: 'var(--eco-text-secondary)',
          maxWidth: '600px',
          margin: '0 auto',
          lineHeight: 1.6
        }}>
          Every action counts. Explore our guides and tips to transform waste into wealth and build a greener future for our nation.
        </p>
      </div>

      <div className="container" style={{ marginTop: '-40px' }}>

        {/* ── Section 2: Category Filter Bar ── */}
        <div style={{
          background: 'var(--eco-surface)',
          padding: '16px',
          borderRadius: '16px',
          boxShadow: 'var(--shadow-md)',
          marginBottom: '48px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: '12px',
          flexWrap: 'wrap',
          border: '1px solid var(--eco-border)',
          position: 'relative',
          zIndex: 10
        }}>
          {CATEGORIES.map(c => (
            <button key={c}
              onClick={() => { setCategory(c); setPage(0); }}
              style={{
                padding: '10px 20px',
                borderRadius: '10px',
                border: 'none',
                cursor: 'pointer',
                fontSize: '13px',
                fontWeight: 600,
                transition: 'all 0.3s ease',
                background: category === c ? 'var(--eco-primary)' : 'transparent',
                color: category === c ? 'white' : 'var(--eco-text-secondary)',
              }}
              onMouseEnter={(e) => { if (category !== c) e.target.style.background = 'var(--eco-bg-secondary)'; }}
              onMouseLeave={(e) => { if (category !== c) e.target.style.background = 'transparent'; }}
            >
              {c === 'ALL' ? 'All Articles' : c.replace(/_/g, ' ')}
            </button>
          ))}
        </div>

        {error && <div style={{
          padding: '20px',
          background: '#fee2e2',
          color: '#b91c1c',
          borderRadius: '12px',
          textAlign: 'center',
          marginBottom: '24px'
        }}>⚠️ {error}</div>}

        {loading ? (
          <div style={{ minHeight: '400px', display: 'flex', alignItems: 'center' }}>
            <Loader text="Fetching latest environmental insights..." />
          </div>
        ) : blogs.length === 0 ? (
          <EmptyState
            icon="🌿"
            title="Growing Knowledge..."
            subtitle="Our environmentalists are currently drafting new guides. Check back in a few days!"
          />
        ) : (
          <>
            {/* ── Section 3: Featured Content ── */}
            {page === 0 && category === 'ALL' && <FeaturedBlog blog={blogs[0]} />}

            {/* ── Section 4: Blog Grid ── */}
            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))',
              gap: '32px'
            }}>
              {blogs.map((b, idx) => {
                // If it's page 1 and ALL, we skip the first one since it's "Featured"
                if (page === 0 && category === 'ALL' && idx === 0) return null;
                return <BlogCard key={b.id} blog={b} />;
              })}
            </div>

            {/* ── Section 5: Pagination ── */}
            {totalPages > 1 && (
              <div style={{
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                gap: '8px',
                marginTop: '60px'
              }}>
                <Button
                  variant="secondary"
                  disabled={page === 0}
                  onClick={() => setPage(p => p - 1)}
                  style={{ borderRadius: '12px' }}
                >
                  ← Previous
                </Button>

                <div style={{ display: 'flex', gap: '5px' }}>
                  {Array.from({ length: totalPages }, (_, i) => (
                    <button
                      key={i}
                      onClick={() => setPage(i)}
                      style={{
                        width: '40px',
                        height: '40px',
                        borderRadius: '10px',
                        border: '1px solid var(--eco-border)',
                        background: page === i ? 'var(--eco-primary)' : 'white',
                        color: page === i ? 'white' : 'var(--eco-text)',
                        cursor: 'pointer',
                        fontWeight: 600,
                        transition: '0.2s'
                      }}
                    >
                      {i + 1}
                    </button>
                  ))}
                </div>

                <Button
                  variant="secondary"
                  disabled={page >= totalPages - 1}
                  onClick={() => setPage(p => p + 1)}
                  style={{ borderRadius: '12px' }}
                >
                  Next Page →
                </Button>
              </div>
            )}
          </>
        )}

        {/* ── Section 6: Info Banner ── */}
        <div style={{
          marginTop: '100px',
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
          gap: '40px',
          alignItems: 'center'
        }}>
          <div>
            <h2 style={{ fontSize: '28px', fontWeight: 800, marginBottom: '16px' }}>Why awareness matters?</h2>
            <p style={{ color: 'var(--eco-text-secondary)', lineHeight: 1.7 }}>
              India produces over 62 million tons of waste annually. By reading and sharing these insights, you help reduce landfill pressure and promote circular economy practices in your community.
            </p>
          </div>
          <NewsletterBox />
        </div>

      </div>

      {/* ── Section 7: Swachh Bharat Bottom Bar ── */}
      <div style={{
        marginTop: '80px',
        padding: '40px',
        textAlign: 'center',
        borderTop: '1px dashed var(--eco-border)'
      }}>
        <div style={{ opacity: 0.5, marginBottom: '20px' }}>
          <span style={{ fontSize: '14px', letterSpacing: '4px', textTransform: 'uppercase' }}>Join the Mission</span>
        </div>
        <div style={{ display: 'flex', justifyContent: 'center', gap: '30px', flexWrap: 'wrap' }}>
          <div style={{ textAlign: 'center' }}>
            <h4 style={{ color: 'var(--eco-primary)', fontSize: '24px' }}>10K+</h4>
            <span style={{ fontSize: '12px', color: 'var(--eco-text-muted)' }}>Daily Readers</span>
          </div>
          <div style={{ textAlign: 'center' }}>
            <h4 style={{ color: 'var(--eco-primary)', fontSize: '24px' }}>500+</h4>
            <span style={{ fontSize: '12px', color: 'var(--eco-text-muted)' }}>Green Tips</span>
          </div>
          <div style={{ textAlign: 'center' }}>
            <h4 style={{ color: 'var(--eco-primary)', fontSize: '24px' }}>50+</h4>
            <span style={{ fontSize: '12px', color: 'var(--eco-text-muted)' }}>Indian Cities</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BlogsPage;
